-- HG shared platform migration (schema: lms)
-- Source: lms-hg/supabase/migrations/20260927135000_retire_unmerged_transactional_rpcs.sql
-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- The 20260824151430/151500/151732 migrations (branch
-- refactor/transactional-correctness, never merged) were applied to the cloud
-- database. Their definer RPCs hard-code the legacy roles: role = 'admin' is
-- treated as full access and role = 'teacher' via teacher_assignments. After
-- Phase 1 maps teacher -> 'admin', every scoped Admin would inherit full
-- access through these authenticated-callable functions, bypassing Phase 1
-- permissions; several also reference lms.events, which Phase 2 renames.
-- No application code on main calls them. Remove them BEFORE the role change.
-- reminder_deliveries and learner_progress_timestamp_state_check are kept.
BEGIN;
DO $retire$
DECLARE
  fn regprocedure;
BEGIN
  FOR fn IN
    SELECT p.oid::regprocedure FROM pg_proc p
    WHERE p.pronamespace = 'lms'::regnamespace
      AND p.proname IN ('actor_can_manage_event', 'actor_can_manage_learner', 'add_learners_to_event_atomic',
        'assert_rpc_actor', 'claim_due_module_reminders', 'complete_module_atomic', 'create_module_atomic',
        'enroll_in_event_atomic', 'finalize_module_version_atomic', 'mark_reminder_failed', 'mark_reminder_sent',
        'reopen_module_atomic', 'reorder_modules_atomic', 'save_reflection_atomic', 'start_module_atomic')
  LOOP
    EXECUTE format('DROP FUNCTION %s', fn);
  END LOOP;
END;
$retire$;
COMMIT;
